/**
 * Accurate India geometry (derived from datameet/maps india-composite,
 * simplified). Equirectangular projection with latitude aspect correction.
 * Generated by scripts — regenerate rather than hand-edit.
 */

export const INDIA_VIEW = { w: 100, h: 111.93 } as const;

const LON_MIN = 68.17202758800005;
const LON_MAX = 97.39535870500004;
const LAT_MIN = 6.752916814000059;
const LAT_MAX = 37.095811;
const X_SCALE = 0.9276775642751994;
const GEO_W = (LON_MAX - LON_MIN) * X_SCALE;
const GEO_H = LAT_MAX - LAT_MIN;

/** Project lon/lat into the INDIA_VIEW svg coordinate space. */
export function project(lon: number, lat: number): { x: number; y: number } {
  return {
    x: Math.round((((lon - LON_MIN) * X_SCALE) / GEO_W) * INDIA_VIEW.w * 100) / 100,
    y: Math.round(((LAT_MAX - lat) / GEO_H) * INDIA_VIEW.h * 100) / 100,
  };
}

