function pointInRing(lon: number, lat: number, ring: [number, number][]): boolean {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    if (yi > lat !== yj > lat && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi)
      inside = !inside;
  }
  return inside;
}

/** Dot-matrix fill of the mainland, in view space. step = grid degrees. */
export function indiaDots(step = 1.1): { x: number; y: number }[] {
  const dots: { x: number; y: number }[] = [];
  for (let lat = LAT_MIN; lat <= LAT_MAX; lat += step) {
    const offset = (Math.round(lat / step) % 2) * (step / 2);
    for (let lon = LON_MIN + offset; lon <= LON_MAX; lon += step) {
      if (pointInRing(lon, lat, MAINLAND_RING)) dots.push(project(lon, lat));
    }
  }
  return dots;
}

